create table if not exists public.athr_billing_plans (
plan_code text primary key,name_ar text not null,name_en text not null,audience text not null check(audience in('individual','business','both')),
tagline_ar text not null,description_ar text not null,features jsonb not null default '[]'::jsonb,price_minor bigint,
currency text not null default 'EGP' check(currency='EGP'),billing_interval text not null default 'month' check(billing_interval in('none','month','year','custom')),
included_credits integer,display_order integer not null default 0,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
check(price_minor is null or price_minor>=0),check(included_credits is null or included_credits>=0));
insert into public.athr_billing_plans(plan_code,name_ar,name_en,audience,tagline_ar,description_ar,features,price_minor,currency,billing_interval,included_credits,display_order,is_active) values
('free','المجانية','Free','both','ابدأ واستفد بحرية','وصول مستمر للخدمات الأساسية مع حدود استخدام عادلة.','["محادثات أساسية","الوصول إلى المساحات الأساسية المتاحة","حفظ الحساب والمشروعات","إمكانية الترقية في أي وقت"]'::jsonb,0,'EGP','none',null,1,true),
('plus','بلس','Plus','individual','للاستخدام اليومي النشط','إمكانيات أوسع وحدود أعلى للمستخدمين الأفراد.','["حدود استخدام أعلى","إمكانيات إضافية للعقول المتخصصة","أدوات أوسع للتعلم والإبداع","رصيد شهري حسب تفاصيل الباقة"]'::jsonb,null,'EGP','month',null,2,true),
('pro','برو','Pro','individual','للاستخدام المكثف والإنتاج','قدرات متقدمة وأولوية أعلى للمستخدمين المحترفين.','["حدود استخدام مرتفعة","إمكانيات متقدمة للنماذج والأدوات المتاحة","أولوية معالجة أعلى عند توفرها","رصيد شهري أكبر حسب تفاصيل الباقة"]'::jsonb,null,'EGP','month',null,3,true),
('business','الأعمال','Business','business','لفرق العمل والمؤسسات','مساحات عمل وإدارة أعضاء وصلاحيات وباقات مخصصة.','["مساحة عمل للفريق","إدارة الأعضاء والصلاحيات","إدارة استخدام الفريق","باقة جاهزة أو عرض مخصص للشركات"]'::jsonb,null,'EGP','custom',null,4,true)
on conflict(plan_code) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,audience=excluded.audience,tagline_ar=excluded.tagline_ar,description_ar=excluded.description_ar,features=excluded.features,display_order=excluded.display_order,is_active=excluded.is_active,updated_at=now();
create table if not exists public.athr_user_entitlements(user_id uuid primary key references auth.users(id) on delete cascade,plan_code text not null default 'free' references public.athr_billing_plans(plan_code),status text not null default 'active' check(status in('active','past_due','paused','canceled')),started_at timestamptz not null default now(),current_period_end timestamptz,updated_at timestamptz not null default now());
create table if not exists public.athr_credit_wallets(user_id uuid primary key references auth.users(id) on delete cascade,balance integer not null default 0 check(balance>=0),lifetime_purchased integer not null default 0 check(lifetime_purchased>=0),updated_at timestamptz not null default now());
create table if not exists public.athr_credit_packs(pack_code text primary key,name_ar text not null,credits integer not null check(credits>0),price_minor bigint,currency text not null default 'EGP' check(currency='EGP'),display_order integer not null default 0,is_active boolean not null default true,check(price_minor is null or price_minor>=0));
insert into public.athr_credit_packs(pack_code,name_ar,credits,price_minor,currency,display_order,is_active) values('starter','رصيد إضافي صغير',100,null,'EGP',1,true),('plus','رصيد إضافي متوسط',300,null,'EGP',2,true),('max','رصيد إضافي كبير',750,null,'EGP',3,true) on conflict(pack_code) do update set name_ar=excluded.name_ar,credits=excluded.credits,display_order=excluded.display_order,is_active=excluded.is_active;
create table if not exists public.athr_credit_ledger(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,delta integer not null check(delta<>0),reason text not null check(reason in('purchase','subscription_grant','usage','refund','owner_adjustment')),reference text,created_at timestamptz not null default now());
create index if not exists athr_credit_ledger_user_created_idx on public.athr_credit_ledger(user_id,created_at desc);
create table if not exists public.athr_billing_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,provider text not null check(provider in('google_play','paymob','manual')),provider_payment_id text,product_type text not null check(product_type in('subscription','credit_pack')),product_ref text not null,amount_minor bigint not null check(amount_minor>=0),currency text not null default 'EGP' check(currency='EGP'),status text not null default 'pending' check(status in('pending','paid','failed','refunded','canceled')),created_at timestamptz not null default now(),verified_at timestamptz,unique(provider,provider_payment_id));
create index if not exists athr_billing_transactions_user_created_idx on public.athr_billing_transactions(user_id,created_at desc);
create table if not exists public.athr_subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,plan_code text not null references public.athr_billing_plans(plan_code),provider text not null check(provider in('google_play','paymob','manual')),provider_subscription_id text,status text not null check(status in('pending','active','past_due','paused','canceled','expired')),started_at timestamptz,current_period_end timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists athr_subscriptions_user_created_idx on public.athr_subscriptions(user_id,created_at desc);
create or replace function public.athr_initialize_billing_account() returns trigger language plpgsql security definer set search_path='' as $$ begin
insert into public.athr_user_entitlements(user_id,plan_code,status) values(new.id,'free','active') on conflict(user_id) do nothing;
insert into public.athr_credit_wallets(user_id,balance,lifetime_purchased) values(new.id,0,0) on conflict(user_id) do nothing;return new;end;$$;
drop trigger if exists athr_initialize_billing_account on auth.users;
create trigger athr_initialize_billing_account after insert on auth.users for each row execute function public.athr_initialize_billing_account();
insert into public.athr_user_entitlements(user_id,plan_code,status) select id,'free','active' from auth.users on conflict(user_id) do nothing;
insert into public.athr_credit_wallets(user_id,balance,lifetime_purchased) select id,0,0 from auth.users on conflict(user_id) do nothing;
alter table public.athr_billing_plans enable row level security;alter table public.athr_user_entitlements enable row level security;alter table public.athr_credit_wallets enable row level security;alter table public.athr_credit_packs enable row level security;alter table public.athr_credit_ledger enable row level security;alter table public.athr_billing_transactions enable row level security;alter table public.athr_subscriptions enable row level security;
drop policy if exists "Public can view active ATHR plans" on public.athr_billing_plans;create policy "Public can view active ATHR plans" on public.athr_billing_plans for select to anon,authenticated using(is_active=true);
drop policy if exists "Public can view active ATHR credit packs" on public.athr_credit_packs;create policy "Public can view active ATHR credit packs" on public.athr_credit_packs for select to anon,authenticated using(is_active=true);
drop policy if exists "Users can view own ATHR entitlement" on public.athr_user_entitlements;create policy "Users can view own ATHR entitlement" on public.athr_user_entitlements for select to authenticated using((select auth.uid())=user_id);
drop policy if exists "Users can view own ATHR credit wallet" on public.athr_credit_wallets;create policy "Users can view own ATHR credit wallet" on public.athr_credit_wallets for select to authenticated using((select auth.uid())=user_id);
drop policy if exists "Users can view own ATHR credit ledger" on public.athr_credit_ledger;create policy "Users can view own ATHR credit ledger" on public.athr_credit_ledger for select to authenticated using((select auth.uid())=user_id);
drop policy if exists "Users can view own ATHR billing transactions" on public.athr_billing_transactions;create policy "Users can view own ATHR billing transactions" on public.athr_billing_transactions for select to authenticated using((select auth.uid())=user_id);
drop policy if exists "Users can view own ATHR subscriptions" on public.athr_subscriptions;create policy "Users can view own ATHR subscriptions" on public.athr_subscriptions for select to authenticated using((select auth.uid())=user_id);
revoke all on public.athr_billing_plans,public.athr_user_entitlements,public.athr_credit_wallets,public.athr_credit_packs,public.athr_credit_ledger,public.athr_billing_transactions,public.athr_subscriptions from anon,authenticated;
grant select on public.athr_billing_plans,public.athr_credit_packs to anon,authenticated;
grant select on public.athr_user_entitlements,public.athr_credit_wallets,public.athr_credit_ledger,public.athr_billing_transactions,public.athr_subscriptions to authenticated;
grant all on public.athr_billing_plans,public.athr_user_entitlements,public.athr_credit_wallets,public.athr_credit_packs,public.athr_credit_ledger,public.athr_billing_transactions,public.athr_subscriptions to service_role;
revoke all on function public.athr_initialize_billing_account() from public,anon,authenticated;